export type ParsedCreateProjectInstruction<
  TProgram extends string = typeof AXEL_V2_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    payer: TAccountMetas[0];
    admin: TAccountMetas[1];
    config: TAccountMetas[2];
    /** A fresh keypair; the share mint is created at this address. */
    shareMint: TAccountMetas[3];
    project: TAccountMetas[4];
    extraAccountMetas: TAccountMetas[5];
    paymentMint: TAccountMetas[6];
    escrowVault: TAccountMetas[7];
    revenueVault: TAccountMetas[8];
    shareTokenProgram: TAccountMetas[9];
    paymentTokenProgram: TAccountMetas[10];
    systemProgram: TAccountMetas[11];
  };
  data: CreateProjectInstructionData;
};

export function parseCreateProjectInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedCreateProjectInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      admin: getNextAccount(),
      config: getNextAccount(),
      shareMint: getNextAccount(),
      project: getNextAccount(),
      extraAccountMetas: getNextAccount(),
      paymentMint: getNextAccount(),
      escrowVault: getNextAccount(),
      revenueVault: getNextAccount(),
      shareTokenProgram: getNextAccount(),
      paymentTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getCreateProjectInstructionDataDecoder().decode(instruction.data),
  };
}
